using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<ShipmentDto>> GetShipmentsAsync();
    Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<ShipmentDto?> CreateShipmentAsync(CreateShipmentRequest request);
    Task<bool> UpdateShipmentStatusAsync(int id, UpdateShipmentStatusRequest request);
}

public class ShipmentService : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentService(HttpClient http) => _http = http;

    public async Task<List<ShipmentDto>> GetShipmentsAsync()
    {
        return await _http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? [];
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var response = await _http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<ShipmentDto>();
    }

    public async Task<ShipmentDto?> CreateShipmentAsync(CreateShipmentRequest request)
    {
        var response = await _http.PostAsJsonAsync("api/shipments", request);
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<ShipmentDto>();
    }

    public async Task<bool> UpdateShipmentStatusAsync(int id, UpdateShipmentStatusRequest request)
    {
        var response = await _http.PutAsJsonAsync($"api/shipments/{id}/status", request);
        return response.IsSuccessStatusCode;
    }
}

