using Microsoft.AspNetCore.Authorization;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments");

        // All shipments — dispatchers only
        group.MapGet("", [Authorize(Roles = "Dispatcher")] async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.CreatedUtc)
                .Select(s => ToDto(s))
                .ToListAsync();
            return Results.Ok(shipments);
        });

        // Track by tracking number — any authenticated user
        group.MapGet("track/{trackingNumber}", [Authorize] async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(ToDto(shipment));
        });

        // Create shipment — dispatchers only
        group.MapPost("", [Authorize(Roles = "Dispatcher")] async (CreateShipmentRequest request, ApplicationDbContext db) =>
        {
            var shipment = new Shipment
            {
                TrackingNumber = GenerateTrackingNumber(),
                Origin = request.Origin,
                Destination = request.Destination,
                RecipientName = request.RecipientName,
                RecipientEmail = request.RecipientEmail,
                Description = request.Description,
                Status = (int)ShipmentStatus.Pending,
                CreatedUtc = DateTime.UtcNow,
                EstimatedDeliveryUtc = request.EstimatedDeliveryUtc
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"api/shipments/track/{shipment.TrackingNumber}", ToDto(shipment));
        });

        // Update status — dispatchers only
        group.MapPut("{id:int}/status", [Authorize(Roles = "Dispatcher")] async (int id, UpdateShipmentStatusRequest request, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = (int)request.Status;
            await db.SaveChangesAsync();
            return Results.Ok(ToDto(shipment));
        });
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentStatus)s.Status,
        CreatedUtc = s.CreatedUtc,
        EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
        RecipientName = s.RecipientName,
        RecipientEmail = s.RecipientEmail,
        Description = s.Description
    };

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}";
    }
}

using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Data;

public static class SeedData
{
    public static async Task InitializeAsync(IServiceProvider services)
    {
        using var scope = services.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        await db.Database.MigrateAsync();

        var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();
        string[] roles = ["Dispatcher", "Customer"];
        foreach (var role in roles)
        {
            if (!await roleManager.RoleExistsAsync(role))
                await roleManager.CreateAsync(new IdentityRole(role));
        }

        var userManager = scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();

        // Seed dispatcher account
        if (await userManager.FindByEmailAsync("dispatcher@shipmenttracker.com") is null)
        {
            var dispatcher = new ApplicationUser
            {
                UserName = "dispatcher@shipmenttracker.com",
                Email = "dispatcher@shipmenttracker.com",
                EmailConfirmed = true
            };
            await userManager.CreateAsync(dispatcher, "Dispatch3r!");
            await userManager.AddToRoleAsync(dispatcher, "Dispatcher");
        }

        // Seed customer account
        if (await userManager.FindByEmailAsync("customer@example.com") is null)
        {
            var customer = new ApplicationUser
            {
                UserName = "customer@example.com",
                Email = "customer@example.com",
                EmailConfirmed = true
            };
            await userManager.CreateAsync(customer, "Custom3r!");
            await userManager.AddToRoleAsync(customer, "Customer");
        }

        // Seed sample shipments
        if (!await db.Shipments.AnyAsync())
        {
            db.Shipments.AddRange(
                new Shipment
                {
                    TrackingNumber = "SHP-20260601-100001",
