                    TrackingNumber = "SHP-20260601-100002",
                    Origin = "Chicago, IL",
                    Destination = "Miami, FL",
                    Status = (int)ShipmentStatus.Pending,
                    CreatedUtc = DateTime.UtcNow.AddDays(-1),
                    EstimatedDeliveryUtc = DateTime.UtcNow.AddDays(5),
                    RecipientName = "Bob Smith",
                    Description = "Furniture — 1 pallet"
                },
                new Shipment
                {
                    TrackingNumber = "SHP-20260601-100003",
                    Origin = "Seattle, WA",
                    Destination = "Denver, CO",
                    Status = (int)ShipmentStatus.Delivered,
                    CreatedUtc = DateTime.UtcNow.AddDays(-7),
                    EstimatedDeliveryUtc = DateTime.UtcNow.AddDays(-2),
                    RecipientName = "Carol Davis",
                    Description = "Medical supplies"
                },
                new Shipment
                {
                    TrackingNumber = "SHP-20260601-100004",
                    Origin = "Houston, TX",
                    Destination = "Phoenix, AZ",
                    Status = (int)ShipmentStatus.OutForDelivery,
                    CreatedUtc = DateTime.UtcNow.AddDays(-2),
                    EstimatedDeliveryUtc = DateTime.UtcNow,
                    RecipientName = "Dave Wilson",
                    Description = "Auto parts — 3 boxes"
                },
                new Shipment
                {
                    TrackingNumber = "SHP-20260601-100005",
                    Origin = "Boston, MA",
