                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isSearching">
                @(isSearching ? "Searching..." : "Track")
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">
        <strong>Not Found.</strong> No shipment found with tracking number <code>@lastSearched</code>.
        Please check the number and try again.
    </div>
}

@if (shipment is not null)
{
    <div class="card shadow-sm">
        <div class="card-header bg-dark text-white">
            <h5 class="mb-0">Shipment <code class="text-light">@shipment.TrackingNumber</code></h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span></dd>

                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>

                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Recipient</dt>
                        <dd>@(shipment.RecipientName ?? "—")</dd>

                        <dt>Shipped On</dt>
                        <dd>@shipment.CreatedUtc.ToString("MMMM dd, yyyy")</dd>

                        <dt>Estimated Delivery</dt>
                        <dd>
                            @if (shipment.EstimatedDeliveryUtc.HasValue)
                            {
                                <span class="fw-bold">@shipment.EstimatedDeliveryUtc.Value.ToString("MMMM dd, yyyy")</span>
                                @if (shipment.Status != ShipmentStatus.Delivered && shipment.Status != ShipmentStatus.Cancelled)
                                {
                                    var daysLeft = (shipment.EstimatedDeliveryUtc.Value.Date - DateTime.UtcNow.Date).Days;
                                    if (daysLeft > 0)
                                    {
                                        <span class="text-muted ms-2">(@daysLeft day@(daysLeft != 1 ? "s" : "") away)</span>
                                    }
                                    else if (daysLeft == 0)
                                    {
                                        <span class="text-success ms-2">(Today!)</span>
                                    }
                                    else
                                    {
                                        <span class="text-danger ms-2">(Overdue)</span>
                                    }
                                }
                            }
                            else
                            {
                                <span>—</span>
                            }
                        </dd>
                    </dl>
                </div>
            </div>

            @if (!string.IsNullOrEmpty(shipment.Description))
            {
                <hr />
                <p class="mb-0"><strong>Description:</strong> @shipment.Description</p>
            }
        </div>

        <!-- Progress tracker -->
        <div class="card-footer">
            <div class="d-flex justify-content-between text-center">
                @foreach (var step in statusSteps)
                {
                    var isActive = (int)shipment.Status >= (int)step;
                    var isCurrent = shipment.Status == step;
                    <div class="flex-fill">
                        <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(isActive ? "bg-success text-white" : "bg-light text-muted")"
                             style="width: 36px; height: 36px; font-size: 0.9rem;">
                            @(isActive ? "✓" : "○")
                        </div>
                        <div class="small @(isCurrent ? "fw-bold" : "")">@step</div>
                    </div>
                }
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public string? TrackingNumber { get; set; }

    private string searchInput = string.Empty;
    private string? lastSearched;
    private ShipmentDto? shipment;
    private bool notFound;
    private bool isSearching;

    private static readonly ShipmentStatus[] statusSteps =
    [
        ShipmentStatus.Pending,
        ShipmentStatus.PickedUp,
        ShipmentStatus.InTransit,
        ShipmentStatus.OutForDelivery,
        ShipmentStatus.Delivered
    ];

    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            searchInput = TrackingNumber;
            await SearchShipment();
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(searchInput)) return;

        isSearching = true;
        notFound = false;
        lastSearched = searchInput.Trim();

        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(lastSearched);
        notFound = shipment is null;
        isSearching = false;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}
